class AccountInfomation(object):
    def __init__(self, platform, username, fh_interface=None):
        self.platform = platform
        self.username = username
        self.fh_interface = fh_interface


class AccountSecurityInformation(AccountInfomation):
    def __init__(self, platform, username, password, fh_interface=None):
        super(AccountSecurityInformation, self).__init__(platform, username, fh_interface=fh_interface)
        self.password = password


def lookup_accounts(ru_name, fh_interface=None):
    if not ru_name:
        return []
    upper_ru_name = ru_name.upper()
    radio_platform = ""
    for platform, rus in _platform_vs_ru.items():
        if upper_ru_name in rus:
            radio_platform = platform
            break

    if not radio_platform:
        return []

    accounts = []
    for platform_account_record in _ssh_accounts:
        _platfrom = platform_account_record[0]
        _username = platform_account_record[4]
        _password = platform_account_record[5]
        _fh_interface = platform_account_record[6]

        if fh_interface:  # care about fh_interface
            if _platfrom == radio_platform and _fh_interface:
                accounts.append(AccountSecurityInformation(_platfrom, _username, _password, _fh_interface))
        else:
            if _platfrom == radio_platform:
                accounts.append(AccountSecurityInformation(_platfrom, _username, _password, _fh_interface))
    return accounts


def lookup_account(ru_name, username, fh_interface=None):
    accounts = lookup_accounts(ru_name, fh_interface)
    for account in accounts:
        if account.username == username:
            return account
    return None


def supported_rus():
    rus = set()
    for rus_per_platform in _platform_vs_ru.values():
        rus.update(rus_per_platform)
    return rus
